mapper.select:
SELECT ar.*, IFNULL( am.alertNum, 0 ) AS alertNum, IFNULL( sta.starred, 0 ) AS starred FROM alert_rule ar LEFT JOIN ( SELECT rule_id, count( 1 ) AS alertNum FROM alert_message_active GROUP BY rule_id ) am ON ar.id = am.rule_id LEFT JOIN ( SELECT IF(COUNT(1) > 0, 1, 0) AS starred,tid FROM sys_user_starred WHERE TYPE = "alertRule" AND uid = #{params.currentLoginUserID} GROUP BY tid) sta ON ar.id = sta.tid
ar.id in
#{id}
AND locate(#{params.name} , ar.name)
AND ar.type = #{params.type}
AND locate(#{params.expr} , ar.expr)
AND ar.last = #{params.last}
AND locate( #{params.summary} , ar.summary)
AND locate(#{params.description} , ar.description)
AND ar.build_in = #{params.buildIn}
AND ar.state = #{params.state}
AND
starred = #{params.starred}
starred IS NULL
AND FIND_IN_SET(#{receivers[0]}, receiver)
AND FIND_IN_SET(#{receivers[0]}, receiver)
OR FIND_IN_SET(#{receiver}, receiver)
ORDER BY ar.id
